  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Tetrabenazine, which shares the same benzoquinolizine core as the query, has a very low mean oral systemic availability of 0.049 ± 0.032 in patients, with all individual values below 10%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a tetrabenazine prodrug with a modified core, achieves an absolute oral bioavailability of approximately 49% in humans, indicating that core modifications can raise F above 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C62"],
      "claim": "Almorexant, a tetrahydroisoquinoline with a dimethoxyphenyl group, has an absolute oral bioavailability of about 11% in humans, supporting low F for structurally related rigid basic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Verapamil, which contains a dimethoxyphenyl and basic amine side chain similar to the query, has an absolute oral bioavailability of 22.0% in normal subjects, near the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Donepezil, a dimethoxyphenyl-containing basic drug, has an absolute oral bioavailability of 100% in humans, but its overall scaffold is structurally distant from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a tetrabenazine-like benzoquinolizine lactam with a verapamil-like side chain. The closest structural analog, tetrabenazine, has very low oral bioavailability (<10%), and almorexant (a rigid tetrahydroisoquinoline) also shows low F (~11%). Although valbenazine and donepezil demonstrate that related scaffolds can achieve high F, the query's specific combination of a rigid tetrabenazine core and a metabolically labile verapamil-like side chain makes low bioavailability (F < 20%) the better-supported prediction, albeit with substantial uncertainty.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "The metabolic stability of the lactam (amide) core relative to tetrabenazine's ketone is unknown.",
    "The impact of the N-(3-(dimethylamino)propyl) and dimethoxyphenylmethyl substituents on first-pass metabolism and permeability is not directly evidenced.",
    "The query is a hybrid of tetrabenazine and verapamil scaffolds; no close analog with both features has been studied."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C38"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tetrabenazine"
    },
